cy.get('body').then($body => {
  if ($body.find('#table-container').length > 0) {
    cy.wait(2000);
    cy.get('#table-container').then($container => {
      if ($container.text().includes('No hay contenido')) {
        cy.log('Se encontró el elemento que contiene el texto "No hay contenido". Se procede a agregar un valor nuevo');
        cy.get('button.btn.btn-primary').contains('Agregar').should('be.visible').click();
        cy.get('div.modal-body').should('be.visible');
        cy.get('input[placeholder="Ingresa el nombre de la unidad"]').should('be.visible').click().type('cysmoketest');
        cy.get('input[placeholder="Ingresa el nombre corto de la unidad"]').should('be.visible').click().type('cysmoketest');
        cy.get('select[name="valuationCurrency"]').select('USD');
        cy.get('div.d-flex.mt-4.justify-content-end.container').find('button.btn.btn-primary').contains('Agregar').click();
        cy.get('#create-index').should('be.visible');
        cy.wait(2000);
        cy.get('div.ball-loader').should('not.exist');
        cy.get('tbody').first().within(() => {
          cy.get('tr').contains('cysmoketest').should('exist');
          cy.get('tr').contains('USD').should('exist');
        });
      } else {
        cy.log('El elemento existe pero no contiene el texto "No hay contenido".');
        cy.get('button.bg-transparent.border-0.text-dark.p-0.m-0.fw-bold.btn.btn-primary').contains('Nombre').should('be.visible');
        cy.contains('button.bg-transparent.border-0.text-dark.p-0.m-0.fw-bold.btn.btn-primary', 'Nombre corto').should('be.visible');
        cy.contains('button.bg-transparent.border-0.text-dark.p-0.m-0.fw-bold.btn.btn-primary', 'Moneda').should('be.visible');
        cy.get('#table-container').should('be.visible');
        cy.get('div.ball-loader').should('not.exist');
      }
    });
  } else {
    cy.log('El elemento #table-container no existe.');
  }
});

