cy.get('#IndexedUnitsOfAccount-Table tbody tr').each($tr => {
  const rowText = $tr.text();
  if (rowText.includes('cysmoketest') && rowText.includes('USD')) {
    cy.wrap($tr).trigger('mouseover'); // Activa el evento hover para mostrar el botón
    cy.wrap($tr).within(() => {
      cy.get('button[name="Desactivar"]').should('be.visible').click();
    });
    cy.get('div.border-0.modal-header').contains('Desactivar unidad indexada').should('be.visible');
    cy.get('div.modal-body').should('be.visible');
    cy.contains('button.btn.btn-danger', 'Desactivar').should('be.visible');
    cy.contains('button.btn.btn-danger', 'Desactivar').should('be.visible').click();
    // Se valida que aparezca el cartel de alerta que confirma la eliminación
    cy.get('#deactivate-index').should('be.visible');
    // Salimos del loop después de encontrar y eliminar la fila
    return false;
